WITH FilteredAccounts AS (SELECT * FROM accounts WHERE balance >= 76000 OR opened_date BETWEEN '2023-06-01' AND '2023-09-09'), summary AS (SELECT account_type, SUM(CASE WHEN status = 'OPEN' THEN 1 ELSE 0 END) AS open_count, ROUND((100 * SUM(CASE WHEN status = 'OPEN' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_open FROM FilteredAccounts GROUP BY account_type) SELECT account_type, open_count, pct_open FROM summary WHERE pct_open < 60 ORDER BY pct_open
